-- DMF0042 권한 메타 동기화 (사내 → 클라우드) — 2026-07-30
-- 증상: 클라우드에서 DMF0042 화면 오픈 시·조회 시 '권한없음'
-- 원인 후보 1순위: 클라우드 권한 메타 3테이블 중 일부 행 누락 (SHT_NM 단위 누락 포함)
--   BE CustomAuthorizationManager 는 (MNU_ID, SHT_NM, MNU_BTN_CD) × 사용자그룹 으로 API 호출을 검사한다.
--   화면 오픈 시점에도 컬럼/Measure/콤보 fetch 가 일어나므로 SEARCH 권한 1건만 없어도 즉시 '권한없음'.
-- 본 스크립트는 **INSERT-only + USE_YN 정정** (삭제 없음). 멱등 — 재실행 무해.
--
-- ⚠️ 먼저 아래 [진단] 을 클라우드에서 실행해 사내 기대값과 대조할 것.

-- ════════ [진단] 클라우드에서 실행 → 사내 기대값과 비교 ════════
--   기대값(사내 실측 2026-07-30): 메뉴권한 6 / 배선 23 / 버튼권한 122
SELECT 'MNU_MPG' T, COUNT(*) CNT FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID='DMF0042'
 UNION ALL SELECT 'BTN_MPG', COUNT(*) FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='DMF0042'
 UNION ALL SELECT 'USER_GR_BTN', COUNT(*) FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='DMF0042';

--   시트별 상세 (어느 시트가 빠졌는지 바로 보인다)
SELECT SHT_NM, COUNT(DISTINCT MNU_BTN_CD) BTNS, COUNT(*) ROWS_
  FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='DMF0042' GROUP BY SHT_NM ORDER BY 1;

