COMMIT;

-- ════════ [검증] ════════
--   ① 카운트가 사내 기대값과 같아야 한다 (메뉴 6 / 배선 23 / 버튼권한 122)
SELECT 'MNU_MPG' T, COUNT(*) CNT FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID='DMF0042'
 UNION ALL SELECT 'BTN_MPG', COUNT(*) FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='DMF0042'
 UNION ALL SELECT 'USER_GR_BTN', COUNT(*) FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='DMF0042';

--   ② 배선된 API_ID 가 API_M 에 전부 있는가 (0행이어야 한다)
SELECT b.SHT_NM, b.MNU_BTN_CD, b.API_ID FROM SCM_ADM_MNU_BTN_MPG_M b
 WHERE b.MNU_ID='DMF0042'
   AND NOT EXISTS (SELECT 1 FROM SCM_ADM_API_M a WHERE a.API_ID=b.API_ID);

--   ③ API 가 가리키는 SP/PKG 가 존재·VALID 한가 (INVALID·부재 0행이어야 한다)
SELECT a.API_ID, a.API_URL FROM SCM_ADM_MNU_BTN_MPG_M b JOIN SCM_ADM_API_M a ON a.API_ID=b.API_ID
 WHERE b.MNU_ID='DMF0042'
   AND NOT EXISTS (SELECT 1 FROM ALL_OBJECTS o
                    WHERE o.OBJECT_NAME = UPPER(REGEXP_SUBSTR(a.API_URL,'^[^.]+'))
                      AND o.STATUS='VALID');

--   ④ PKG SYNONYM — 어플 계정(클라우드=SCMP_APP)에 PKG_DMF0042 SYNONYM 이 있는가
SELECT OWNER, SYNONYM_NAME, TABLE_OWNER FROM ALL_SYNONYMS WHERE TABLE_NAME LIKE 'PKG_DMF0042%';
--   없으면 어플 계정 세션에서: CREATE OR REPLACE SYNONYM PKG_DMF0042 FOR SCM_MGR.PKG_DMF0042;

--   ⑤ 그래도 '권한없음' 이면 BE 가 실제로 어느 키로 막는지 로그에서 확인
SELECT LOG_ST_DTM, MNU_ID, MNU_BTN_CD, SHT_NM, EXCT_MSG_CTN, SYS_LOG_MSG_CTN
  FROM SCM_COM_SYS_LOG WHERE MNU_ID='DMF0042' ORDER BY LOG_ST_DTM DESC FETCH FIRST 20 ROWS ONLY;
